"""Interface web completa do Portal Motorista (mini painel operacional)."""
from __future__ import annotations

import json

from .driver_portal_access import activation_token_pending
from .driver_portal_dtos import portal_branding
from .driver_portal_panel import public_panel_config
from .portal_auth import driver_has_password


def render_driver_portal_page(app, driver, slug):
    branding = portal_branding(app)
    panel = public_panel_config(driver)
    empresa = panel.get("business_name") or branding["empresa"]
    logo_url = panel.get("logo_url") or branding.get("logo_url") or ""
    logo_inner = f'<img src="{logo_url}" alt="logo"/>' if logo_url else empresa[:1]
    activated = driver_has_password(driver)
    pending_token = activation_token_pending(driver)
    if activated:
        activation_msg = ""
    elif pending_token:
        activation_msg = "Primeiro acesso: informe seu CPF e cole o token de ativacao no campo Senha. Depois defina sua senha permanente."
    else:
        activation_msg = "Token ja utilizado ou expirado. Solicite um novo token ao administrador."
    html = _HTML.replace("__SLUG__", json.dumps(slug))
    html = html.replace("__ACTIVATED__", "true" if activated else "false")
    html = html.replace("__EMPRESA__", empresa)
    html = html.replace("__BUILD__", branding["build"])
    html = html.replace("__DRIVER_NOME__", driver.get("nome", "Motorista"))
    html = html.replace("__CPF_HINT__", driver.get("cpf", ""))
    html = html.replace("__LOGO_INNER__", logo_inner)
    html = html.replace("__ACTIVATION_MSG__", activation_msg)
    html = html.replace("__PRIMARY__", panel.get("primary_color") or "#3b82f6")
    return html


_HTML = r"""<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Portal Motorista — __EMPRESA__</title>
<style>
:root{--bg:#0f1419;--panel:#1a2332;--panel2:#243044;--text:#e8eef7;--muted:#8fa3bf;--primary:__PRIMARY__;--success:#22c55e;--warning:#f59e0b;--danger:#ef4444;--line:#2d3a4f;--radius:14px;--shadow:0 8px 32px rgba(0,0,0,.35)}
*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh}.hidden{display:none!important}
.app{max-width:1180px;margin:0 auto;min-height:100vh;display:flex;flex-direction:column}.topbar{background:var(--panel);border-bottom:1px solid var(--line);padding:14px 18px;display:flex;align-items:center;gap:14px;position:sticky;top:0;z-index:10}
.logo{width:42px;height:42px;border-radius:10px;background:var(--panel2);display:grid;place-items:center;font-weight:700;color:var(--primary);overflow:hidden}.logo img{width:100%;height:100%;object-fit:cover}
.brand h1{margin:0;font-size:1rem}.brand p{margin:2px 0 0;font-size:.78rem;color:var(--muted)}.spacer{flex:1}.chip{font-size:.72rem;padding:4px 10px;border-radius:999px;background:var(--panel2);color:var(--muted)}
.content{flex:1;padding:16px;padding-bottom:94px}.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:16px;box-shadow:var(--shadow);margin-bottom:14px}.grid{display:grid;gap:12px}.grid-2{grid-template-columns:repeat(2,1fr)}.grid-3{grid-template-columns:repeat(3,1fr)}.grid-4{grid-template-columns:repeat(4,1fr)}@media(max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr}}
.stat{text-align:center}.stat .val{font-size:1.6rem;font-weight:700;color:var(--primary)}.stat .lbl{font-size:.78rem;color:var(--muted);margin-top:4px}
label{display:block;font-size:.82rem;color:var(--muted);margin-bottom:6px}input,select,textarea{width:100%;padding:11px 12px;border-radius:10px;border:1px solid var(--line);background:var(--panel2);color:var(--text);font-size:.92rem}textarea{min-height:92px;resize:vertical}
button{cursor:pointer;border:none;border-radius:10px;padding:11px 14px;font-weight:600;font-size:.9rem}.btn{background:var(--primary);color:#fff}.btn-outline{background:transparent;border:1px solid var(--line);color:var(--text)}.btn-success{background:var(--success);color:#fff}.btn-danger{background:var(--danger);color:#fff}.btn-block{width:100%}
.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.nav{position:fixed;bottom:0;left:0;right:0;background:var(--panel);border-top:1px solid var(--line);display:flex;justify-content:space-around;padding:8px 4px 10px;z-index:20}.nav button{background:transparent;color:var(--muted);font-size:.68rem;display:flex;flex-direction:column;align-items:center;gap:4px;padding:6px 7px}.nav button.active{color:var(--primary)}
.table{width:100%;border-collapse:collapse;font-size:.86rem}.table th,.table td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.badge{display:inline-block;padding:3px 8px;border-radius:999px;font-size:.72rem;background:var(--panel2)}.badge.ok{background:rgba(34,197,94,.15);color:var(--success)}.badge.warn{background:rgba(245,158,11,.15);color:var(--warning)}.badge.err{background:rgba(239,68,68,.15);color:var(--danger)}.badge.mine{background:rgba(59,130,246,.18);color:#93c5fd}
.notice{border-left:3px solid var(--primary);padding:10px 12px;background:var(--panel2);border-radius:8px;margin-bottom:10px}.notice.unread{border-left-color:var(--warning)}.login-wrap{max-width:420px;margin:40px auto}.muted{color:var(--muted);font-size:.85rem}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.filters button{padding:8px 12px}.filters button.active{background:var(--primary);color:#fff}.detail-row{display:grid;grid-template-columns:140px 1fr;gap:8px;margin-bottom:8px;font-size:.9rem}.alert{padding:10px 12px;border-radius:8px;margin-bottom:12px;font-size:.85rem}.alert.err{background:rgba(239,68,68,.12);color:#fecaca}.alert.ok{background:rgba(34,197,94,.12);color:#bbf7d0}
</style>
</head>
<body>
<div class="app">
<header class="topbar"><div class="logo">__LOGO_INNER__</div><div class="brand"><h1 id="brandTitle">__EMPRESA__</h1><p>Mini painel motorista · Build __BUILD__</p></div><div class="spacer"></div><span class="chip">__DRIVER_NOME__</span><button class="btn-outline hidden" id="logoutBtn" type="button">Sair</button></header>
<main class="content">
<section id="view-login" class="login-wrap"><div class="card"><h2>Entrar no portal</h2><p class="muted">Motorista: <strong>__DRIVER_NOME__</strong></p><div id="loginAlert" class="alert err hidden"></div><label for="cpf">CPF ou identificacao</label><input id="cpf" inputmode="numeric" value="__CPF_HINT__"/><label for="password" style="margin-top:12px">Senha</label><input id="password" type="password" placeholder="Senha do portal ou token de ativacao"/><button class="btn btn-block" id="loginBtn" type="button" style="margin-top:16px">Entrar</button><p class="muted" style="margin-top:14px">__ACTIVATION_MSG__</p></div></section>
<section id="view-set-password" class="login-wrap hidden"><div class="card"><h2>Defina sua senha</h2><p class="muted">Token validado. Crie uma senha permanente para acessar o portal.</p><div id="setPasswordAlert" class="alert err hidden"></div><label>Nova senha</label><input id="newPassword" type="password"/><label style="margin-top:12px">Repita a senha</label><input id="newPassword2" type="password"/><button class="btn btn-block" id="setPasswordBtn" type="button" style="margin-top:16px">Salvar senha e continuar</button></div></section>
<section id="view-dashboard" class="hidden"><div class="grid grid-4"><div class="card stat"><div class="val" id="cardHoje">0</div><div class="lbl">Reservas Hoje</div></div><div class="card stat"><div class="val" id="cardProximas">0</div><div class="lbl">Proximas</div></div><div class="card stat"><div class="val" id="cardMinhas">0</div><div class="lbl">Minhas</div></div><div class="card stat"><div class="val" id="cardAtribuidas">0</div><div class="lbl">Atribuidas</div></div></div><div class="card"><h3>Proximas reservas</h3><div id="dashList"></div></div></section>
<section id="view-reservations" class="hidden"><div class="card"><h3>Reservas</h3><div class="filters"><button type="button" class="active" data-filter="all">Todas</button><button type="button" data-filter="mine">Minhas</button><button type="button" data-filter="assigned">Atribuidas</button><button type="button" data-filter="today">Hoje</button><button type="button" data-filter="week">Semana</button><button type="button" class="btn" onclick="setView('reservation-form')">+ Nova reserva</button></div><div style="overflow-x:auto"><table class="table"><thead><tr><th>Origem</th><th>Cliente</th><th>Data</th><th>Trajeto</th><th>Status</th></tr></thead><tbody id="agendaBody"></tbody></table></div></div></section>
<section id="view-reservation-form" class="hidden"><div class="card"><h3>Nova reserva propria</h3><div id="reservationAlert" class="alert hidden"></div><div class="grid grid-2"><div><label>Cliente salvo</label><select id="resClient"><option value="">Cadastrar/informar manualmente</option></select></div><div><label>Tipo cliente</label><select id="resTipoCliente"><option value="fisica">Pessoa fisica</option><option value="juridica">Empresa</option></select></div><div><label>Nome / Razao social</label><input id="resCliente"/></div><div><label>Documento</label><input id="resDocumento"/></div><div><label>Telefone</label><input id="resTelefone"/></div><div><label>Email</label><input id="resEmail"/></div><div><label>Origem</label><input id="resOrigem"/></div><div><label>Destino</label><input id="resDestino"/></div><div><label>Data</label><input id="resData" placeholder="dd/mm/aaaa"/></div><div><label>Hora</label><input id="resHora" placeholder="08:00"/></div><div><label>Passageiros</label><input id="resPassageiros" value="1"/></div><div><label>Valor</label><input id="resValor" placeholder="R$ 0,00"/></div></div><label style="margin-top:12px">Observacoes</label><textarea id="resObs"></textarea><div class="actions"><button class="btn" type="button" onclick="createReservation()">Salvar reserva</button><button class="btn-outline" type="button" onclick="setView('reservations')">Cancelar</button></div></div></section>
<section id="view-detail" class="hidden"><div class="card" id="detailCard"></div></section>
<section id="view-clients" class="hidden"><div class="grid grid-2"><div class="card"><h3>Novo cliente centralizado</h3><div id="clientAlert" class="alert hidden"></div><label>Tipo</label><select id="clientTipo"><option value="fisica">Pessoa fisica</option><option value="juridica">Empresa</option></select><label style="margin-top:10px">Nome / Razao social</label><input id="clientNome"/><label style="margin-top:10px">Nome fantasia / Responsavel</label><input id="clientFantasia"/><label style="margin-top:10px">CPF/CNPJ</label><input id="clientDocumento"/><label style="margin-top:10px">Telefone</label><input id="clientTelefone"/><label style="margin-top:10px">Email</label><input id="clientEmail"/><button class="btn btn-block" type="button" style="margin-top:12px" onclick="createClient()">Cadastrar cliente</button></div><div class="card"><h3>Meus clientes</h3><div id="clientsList"></div></div></div></section>
<section id="view-notifications" class="hidden"><div class="card"><h3>Avisos</h3><div id="notifList"></div></div></section>
<section id="view-profile" class="hidden"><div class="card" id="profileCard"></div></section>
<section id="view-settings" class="hidden"><div class="grid grid-2"><div class="card"><h3>Identidade do mini painel</h3><div id="settingsAlert" class="alert hidden"></div><label>Nome comercial</label><input id="setBusiness"/><label style="margin-top:10px">Logo (URL publica)</label><input id="setLogo" placeholder="https://.../logo.png"/><label style="margin-top:10px">Cor principal</label><input id="setColor" placeholder="#3b82f6"/><label style="margin-top:10px">Contrato para aparecer no slip/PDF</label><textarea id="setContract"></textarea><label style="margin-top:10px">Codigo 2FA (se ativo)</label><input id="setTotpCode" inputmode="numeric" maxlength="6"/><button class="btn btn-block" type="button" style="margin-top:12px" onclick="saveSettings()">Salvar configuracoes</button></div><div class="card"><h3>Seguranca 2FA</h3><p class="muted" id="totpStatus">Carregando...</p><div id="totpSetupBox"></div><div class="actions"><button class="btn-outline" type="button" onclick="setupTotp()">Configurar 2FA</button><button class="btn-danger" type="button" onclick="disableTotp()">Desativar 2FA</button></div></div></div></section>
</main>
<nav class="nav hidden" id="bottomNav"><button type="button" data-view="dashboard"><span>⌂</span>Dashboard</button><button type="button" data-view="reservations"><span>📅</span>Reservas</button><button type="button" data-view="clients"><span>👥</span>Clientes</button><button type="button" data-view="notifications"><span>🔔</span>Avisos</button><button type="button" data-view="profile"><span>👤</span>Perfil</button><button type="button" data-view="settings"><span>⚙</span>Ajustes</button></nav>
</div>
<script>
const SLUG=__SLUG__;let token=sessionStorage.getItem('driver_token')||'';let reservations=[];let clients=[];let filter='all';let settings={};
function $(id){return document.getElementById(id)}function show(el){if(el)el.classList.remove('hidden')}function hide(el){if(el)el.classList.add('hidden')}function msg(id,text,ok=false){const el=$(id);el.className='alert '+(ok?'ok':'err');el.textContent=text;show(el)}
async function api(path,body={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slug:SLUG,token,...body})});return r.json()}
function setView(name){['login','set-password','dashboard','reservations','reservation-form','detail','clients','notifications','profile','settings'].forEach(v=>hide($('view-'+v)));show($('view-'+name));document.querySelectorAll('#bottomNav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='reservations')loadReservations();if(name==='clients')loadClients();if(name==='settings')loadSettings();if(name==='notifications')loadNotifications();if(name==='profile')loadProfile()}
function statusBadge(s){const v=(s||'').toLowerCase();let c='badge';if(v.includes('conclu'))c+=' ok';else if(v.includes('cancel'))c+=' err';else if(v.includes('pend')||v.includes('aceitar'))c+=' warn';return `<span class="${c}">${s||'—'}</span>`}
async function doLogin(){hide($('loginAlert'));const res=await fetch('/api/driver/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slug:SLUG,cpf:$('cpf').value,identificacao:$('cpf').value,password:$('password').value})}).then(r=>r.json());if(!res.ok){msg('loginAlert','CPF ou token/senha invalidos.');return}token=res.token;sessionStorage.setItem('driver_token',token);if(res.requires_password_setup){sessionStorage.setItem('driver_pending_password','1');setView('set-password');return}sessionStorage.removeItem('driver_pending_password');await bootApp()}
async function doSetPassword(){hide($('setPasswordAlert'));const p1=$('newPassword').value,p2=$('newPassword2').value;if(p1.length<6)return msg('setPasswordAlert','Senha deve ter pelo menos 6 caracteres.');if(p1!==p2)return msg('setPasswordAlert','As senhas nao conferem.');const res=await api('/api/driver/set-password',{password:p1,password_confirm:p2});if(!res.ok)return msg('setPasswordAlert','Nao foi possivel salvar a senha.');sessionStorage.removeItem('driver_pending_password');await bootApp()}
async function bootApp(){if(!token){setView('login');return}if(sessionStorage.getItem('driver_pending_password')==='1'){setView('set-password');return}const dash=await api('/api/driver/dashboard');if(!dash.ok){token='';sessionStorage.clear();setView('login');return}show($('bottomNav'));show($('logoutBtn'));renderDashboard(dash);await Promise.all([loadReservations(),loadClients(),loadSettings(),loadProfile(),loadNotifications()]);setView('dashboard')}
function renderDashboard(d){$('cardHoje').textContent=d.cards.hoje;$('cardProximas').textContent=d.cards.proximas;$('cardMinhas').textContent=d.cards.minhas||0;$('cardAtribuidas').textContent=d.cards.atribuidas||0;$('dashList').innerHTML=(d.proximas_reservas||[]).map(r=>`<div class="notice" onclick="openDetail('${r.numero}')" style="cursor:pointer"><strong>${r.numero}</strong> <span class="badge ${r.owned_by_driver?'mine':''}">${r.source_label}</span><br>${r.data} ${r.hora||''} · ${r.origem} → ${r.destino} ${statusBadge(r.status)}</div>`).join('')||'<p class="muted">Nenhuma reserva proxima.</p>'}
async function loadReservations(){const res=await api('/api/driver/reservations');if(res.ok)reservations=res.items||[];renderReservations();fillClientSelect()}
function passFilter(r){if(filter==='mine')return r.owned_by_driver;if(filter==='assigned')return !r.owned_by_driver;const d=parseDate(r.data);const today=new Date();today.setHours(0,0,0,0);if(filter==='today')return d&&d.getTime()===today.getTime();if(filter==='week'){const w=new Date(today);w.setDate(w.getDate()+7);return d&&d>=today&&d<=w}return true}
function parseDate(s){if(!s)return null;const p=String(s).slice(0,10).split('/');if(p.length===3)return new Date(+p[2],+p[1]-1,+p[0]);return null}
function renderReservations(){const rows=reservations.filter(passFilter);$('agendaBody').innerHTML=rows.map(r=>`<tr onclick="openDetail('${r.numero}')" style="cursor:pointer"><td><span class="badge ${r.owned_by_driver?'mine':''}">${r.source_label}</span></td><td>${r.cliente||'—'}</td><td>${r.data||'—'} ${r.hora||''}</td><td>${r.origem||'—'} → ${r.destino||'—'}</td><td>${statusBadge(r.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Sem reservas.</td></tr>'}
async function openDetail(numero){const res=await api('/api/driver/reservation',{numero});if(!res.ok)return alert('Reserva nao permitida.');const r=res.item;let edit=r.can_edit?`<h4>Editar minha reserva</h4><div class="grid grid-2"><input id="editOrigem" value="${r.origem||''}"/><input id="editDestino" value="${r.destino||''}"/><input id="editData" value="${r.data||''}"/><input id="editHora" value="${r.hora||''}"/></div><label style="margin-top:10px">Observacoes</label><textarea id="editObs">${r.observacoes||''}</textarea><label>2FA se ativo</label><input id="editTotp" maxlength="6"/><div class="actions"><button class="btn" onclick="updateReservation('${r.numero}')">Salvar edicao</button><button class="btn-danger" onclick="cancelReservation('${r.numero}')">Cancelar reserva</button></div>`:'';$('detailCard').innerHTML=`<h3>Reserva ${r.numero} <span class="badge ${r.owned_by_driver?'mine':''}">${r.source_label}</span></h3><div class="detail-row"><span class="muted">Cliente</span><span>${r.cliente||'—'}</span></div><div class="detail-row"><span class="muted">Data/Hora</span><span>${r.data||'—'} ${r.hora||''}</span></div><div class="detail-row"><span class="muted">Origem</span><span>${r.origem||'—'}</span></div><div class="detail-row"><span class="muted">Destino</span><span>${r.destino||'—'}</span></div><div class="detail-row"><span class="muted">Status</span><span>${statusBadge(r.status)}</span></div><p class="muted">${r.observacoes||''}</p><div class="actions"><a class="btn-outline" href="${r.maps_url}" target="_blank">Abrir rota</a><button class="btn-outline" onclick="downloadPdf('${r.numero}','cliente')">PDF Cliente</button><button class="btn-outline" onclick="downloadPdf('${r.numero}','motorista')">PDF Motorista</button></div><div class="actions" id="statusActions"></div>${edit}`;(res.actions||[]).forEach(a=>{const b=document.createElement('button');b.className='btn-success';b.textContent=a.label;b.onclick=()=>updateStatus(r.numero,a.status);$('statusActions').appendChild(b)});setView('detail')}
async function updateStatus(numero,status){const res=await api('/api/driver/status',{numero,status});if(!res.ok)return alert('Sem permissao.');await loadReservations();openDetail(numero)}
async function updateReservation(numero){const res=await api('/api/driver/reservation-update',{numero,origem:$('editOrigem').value,destino:$('editDestino').value,data:$('editData').value,hora:$('editHora').value,observacoes:$('editObs').value,totp_code:$('editTotp').value});if(!res.ok)return alert(res.error||'Erro');await loadReservations();openDetail(numero)}
async function cancelReservation(numero){if(!confirm('Cancelar esta reserva propria?'))return;const res=await api('/api/driver/reservation-cancel',{numero,totp_code:$('editTotp').value});if(!res.ok)return alert(res.error||'Erro');await loadReservations();openDetail(numero)}
async function createReservation(){const payload={client_id:$('resClient').value,tipo_cliente:$('resTipoCliente').value,cliente:$('resCliente').value,documento:$('resDocumento').value,telefone:$('resTelefone').value,email:$('resEmail').value,origem:$('resOrigem').value,destino:$('resDestino').value,data:$('resData').value,hora:$('resHora').value,passageiros:$('resPassageiros').value,valor:$('resValor').value,observacoes:$('resObs').value};const res=await api('/api/driver/reservation-create',payload);if(!res.ok)return msg('reservationAlert',res.error||'Erro ao salvar.');msg('reservationAlert','Reserva criada com sucesso.',true);await loadReservations();setView('reservations')}
async function downloadPdf(numero,via){const res=await api('/api/driver/reservation-pdf',{numero,via});if(!res.ok)return alert(res.error||'Erro PDF');const bin=atob(res.content_base64);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const blob=new Blob([bytes],{type:res.mime});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=res.filename;a.click();URL.revokeObjectURL(a.href)}
async function loadClients(){const res=await api('/api/driver/clients');if(res.ok)clients=res.items||[];$('clientsList').innerHTML=clients.map(c=>`<div class="notice"><strong>${c.nome}</strong> <span class="badge">${c.tipo_pessoa}</span><br><span class="muted">${c.documento||'—'} · ${c.telefone||'—'} · ${c.email||'—'}</span></div>`).join('')||'<p class="muted">Nenhum cliente cadastrado por voce.</p>';fillClientSelect()}
function fillClientSelect(){const sel=$('resClient');if(!sel)return;const cur=sel.value;sel.innerHTML='<option value="">Cadastrar/informar manualmente</option>'+clients.map(c=>`<option value="${c.id}">${c.tipo_pessoa==='juridica'?'[Empresa]':'[PF]'} ${c.nome}</option>`).join('');sel.value=cur}
async function createClient(){const payload={tipo_pessoa:$('clientTipo').value,nome:$('clientNome').value,nome_fantasia:$('clientFantasia').value,razao_social:$('clientNome').value,responsavel:$('clientFantasia').value,documento:$('clientDocumento').value,telefone:$('clientTelefone').value,email:$('clientEmail').value};const res=await api('/api/driver/client-create',payload);if(!res.ok)return msg('clientAlert',res.error||'Erro ao cadastrar cliente.');msg('clientAlert','Cliente cadastrado no cadastro central.',true);['clientNome','clientFantasia','clientDocumento','clientTelefone','clientEmail'].forEach(id=>$(id).value='');await loadClients()}
async function loadProfile(){const res=await api('/api/driver/profile');if(!res.ok)return;const p=res.profile;$('profileCard').innerHTML=`<h3>${p.nome}</h3><div class="detail-row"><span class="muted">CPF</span><span>${p.cpf_masked||p.cpf||'—'}</span></div><div class="detail-row"><span class="muted">Telefone</span><span>${p.telefone||'—'}</span></div><div class="detail-row"><span class="muted">Email</span><span>${p.email||'—'}</span></div><div class="detail-row"><span class="muted">Cidade/UF</span><span>${p.cidade||'—'} / ${p.estado||'—'}</span></div><div class="detail-row"><span class="muted">CNH</span><span>${p.validade_cnh||'—'}</span></div>`}
async function loadNotifications(){const res=await api('/api/driver/notifications');if(!res.ok)return;$('notifList').innerHTML=(res.items||[]).map(n=>`<div class="notice ${n.lida?'':'unread'}"><strong>${n.titulo}</strong><br><span class="muted">${n.criado_em}</span><br>${n.mensagem}</div>`).join('')||'<p class="muted">Nenhum aviso.</p>'}
async function loadSettings(){const res=await api('/api/driver/settings');if(!res.ok)return;settings=res.settings;$('setBusiness').value=settings.business_name||'';$('setLogo').value=settings.logo_url||'';$('setColor').value=settings.primary_color||'#3b82f6';$('setContract').value=settings.contract_text||'';$('totpStatus').textContent=settings.totp_enabled?'2FA ativo para alteracoes sensiveis.':'2FA inativo.'}
async function saveSettings(){const res=await api('/api/driver/settings-save',{business_name:$('setBusiness').value,logo_url:$('setLogo').value,primary_color:$('setColor').value,contract_text:$('setContract').value,totp_code:$('setTotpCode').value});if(!res.ok)return msg('settingsAlert',res.error||'Erro ao salvar.');msg('settingsAlert','Configuracoes salvas.',true);$('brandTitle').textContent=res.settings.business_name||$('brandTitle').textContent;await loadSettings()}
async function setupTotp(){const res=await api('/api/driver/totp-setup');if(!res.ok)return; $('totpSetupBox').innerHTML=`<p class="muted">Escaneie o QR Code e digite o codigo para ativar.</p><img alt="QR 2FA" src="${res.qr}" style="max-width:180px;background:white;padding:8px;border-radius:8px"/><label>Codigo 2FA</label><input id="totpEnableCode" maxlength="6"/><button class="btn btn-block" onclick="enableTotp()">Ativar 2FA</button>`}
async function enableTotp(){const res=await api('/api/driver/totp-enable',{totp_code:$('totpEnableCode').value});if(!res.ok)return alert(res.error||'Codigo invalido');await loadSettings();$('totpSetupBox').innerHTML=''}
async function disableTotp(){const code=prompt('Codigo 2FA atual');if(code===null)return;const res=await api('/api/driver/totp-disable',{totp_code:code});if(!res.ok)return alert(res.error||'Erro');await loadSettings()}
async function doLogout(){await api('/api/driver/logout');token='';sessionStorage.clear();hide($('bottomNav'));hide($('logoutBtn'));setView('login')}
$('loginBtn').onclick=doLogin;$('setPasswordBtn').onclick=doSetPassword;$('logoutBtn').onclick=doLogout;document.querySelectorAll('#bottomNav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('.filters button[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filters button[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderReservations()});
if(token&&sessionStorage.getItem('driver_pending_password')==='1')setView('set-password');else if(token)bootApp();else setView('login');
</script>
</body>
</html>"""
